/**
 * Основа взята из модуля https://github.yandex-team.ru/morda/mumu/tree/master/packages/tune-logger
 */

'use strict';

const debugLog = require('util').debuglog('streams/error-booster');
const unix = require('unix-dgram');
const { codes, normalizeError } = require('./error');

const MAX_QUEUE_LENGTH = 100;

const getTransport = filename => {
    if (!filename) {
        throw new TypeError('Filename is required');
    }

    const client = unix.createSocket('unix_dgram');

    let connected = false;
    let connecting = false;
    let connectRetries = 1;
    let ready = false;
    let queue = [];

    client.on('error', e => onError(e));

    client.on('connect', () => {
        connected = ready = true;
        connecting = false;
        sendQueue();
        connectRetries = 1;
    });

    client.on('congestion', () => {
        ready = false;
    });

    client.on('writable', () => {
        ready = true;
        sendQueue();
    });

    /**
     * Добавление сообщения в очередь.
     * Очередь ограничена MAX_QUEUE_LENGTH
     * последними сообщениями.
     *
     * @param {Buffer} message сообщение
     * @returns {undefined}
     */
    function addToQueue(message) {
        if (queue.length >= MAX_QUEUE_LENGTH) {
            queue = queue.slice(-MAX_QUEUE_LENGTH / 2);
        }

        queue.push(message);
    }

    /**
     * Отправка очереди сообщений.
     * Вызывается после установки соединения и после отправки очередного сообщения.
     * @returns {undefined}
     */
    function sendQueue() {
        if (!ready || !connected || !queue.length) {
            return;
        }

        const message = queue.shift();

        send(message);
    }

    /**
     * Обработка ошибок. Некоторые ошибки допускают попытку пересоединения
     * (например, если сокет был закрыт).
     * Переподключение возможно только один раз на обработку ошибки connect
     * и один раз при обработке ошибки каждого send.
     *
     * @param {Error} [error] ошибка
     * @param {Buffer} [message] сообшение, которое нужно переотправить
     * @returns {undefined}
     */
    function onError(error, message) {
        error = normalizeError(error);

        if (error.code === codes.ENOTCONN || error.code === codes.EAGAIN) {
            connected = false;

            if (message) {
                addToQueue(message);
            } else if (!connectRetries) {
                debugLog('error on retry', error);

                return;
            }

            connectRetries--;

            connect();
        } else {
            if (error.code === codes.EPERM ||
                error.code === codes.ENOENT ||
                error.code === codes.EACCESS) {
                connected = connecting = ready = false;
            }

            debugLog('unexpected error', error);
        }
    }

    /**
     * Т.е. открытие сокета.
     * @returns {undefined}
     */
    function connect() {
        if (connecting) {
            return;
        }

        connecting = true;
        connected = ready = false;

        client.connect(filename);
    }

    /**
     * Отправка сообщения. Допускает однократную
     * попытку переподключения при ошибке.
     *
     *  @param {Buffer} message сообщение
     *  @returns {undefined}
     */
    function send(message) {
        if (!connected || !ready) {
            addToQueue(message);

            if (!connected) {
                connect();
            }

            return;
        }

        debugLog('sending a message: %s', message);

        client.send(message, error => {
            if (error) {
                onError(error, message);
            } else {
                sendQueue();
            }
        });
    }

    connect();

    return event => {
        const message = Buffer.from(event);

        send(message);
    };
};

module.exports = {
    getTransport,
};
